documents.grouped:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, PARAMCD]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  HOME: {path: home.csv, key: [STUDYID, USUBJID], types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  PLAN: {path: plan.csv, types: {DOSENUM: int, PLANDOSE: float, FIRST: int, LAST: int, REF: int}}
  DM: {path: dm.csv, types: {RFSTDTC: date}}
output: {path: out.csv, columns: [STUDYID, USUBJID, PARAMCD, SEQ, AVAL, X, C, N, M]}
columns:
  - {name: STUDYID, type: str, derivation: VS.STUDYID}
  - {name: USUBJID, type: str, derivation: VS.USUBJID}
  - {name: PARAMCD, type: str}
  - name: SEQ
    type: int
    derivation: {row_number: {window: {group_by: [STUDYID, USUBJID], order_by: [PARAMCD]}}}
  - {name: AVAL, type: float}
  - {name: X, type: float, derivation: 0.0}
  - {name: C, type: str, derivation: "'none'"}
  - {name: N, type: int, derivation: 0}
  - {name: M, type: int, derivation: 0}
rows:
  - id: subject
    dataset: VS
    group_by: [VS.STUDYID, VS.USUBJID]
    derivations:
      PARAMCD: "'MAXBP'"
      AVAL: {aggregate: "MAX(VS.SYSBP)"}

