documents.vitals:
yamaa: "1.0"
type: spec
domain: VS
keys: [USUBJID, VSDY, VSCAT]
output: {path: vs.csv, columns: [USUBJID, VSDY, VSCAT, VSSTRESN]}
input:
  CLINIC: {path: clinic.csv, types: {VSDY: int, SYSBP: int}}
  HOME: {path: home.csv, types: {VSDY: int, SYSBP: int}}
rows:
  - id: clinic
    dataset: CLINIC
    derivations: {USUBJID: CLINIC.USUBJID, VSDY: CLINIC.VSDY, VSCAT: "'CLINIC'", VSSTRESN: CLINIC.SYSBP}
  - id: home
    dataset: HOME
    group_by: [HOME.USUBJID, HOME.VSDY]
    derivations: {USUBJID: HOME.USUBJID, VSDY: HOME.VSDY, VSCAT: "'HOME'"}
columns:
  - {name: USUBJID, type: str}
  - {name: VSDY, type: int}
  - {name: VSCAT, type: str}
  - {name: VSSTRESN, type: float}

