documents.window_row:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
input: {SRC: {path: source.csv, types: {ID: int, VAL: int}}}
output: {path: out.csv, columns: [ID, LOW, SEQ]}
columns:
  - {name: ID, type: int}
  - {name: LOW, type: int}
  - {name: SEQ, type: int}
rows:
  - id: grouped
    group_by: [SRC.ID]
    derivations:
      ID: SRC.ID
      LOW: {aggregate: 'MIN(SRC.VAL)'}
      SEQ: {row_number: {window: {order_by: [ORDER]}}}

